transforms.code:

spoof = value.setup.spoof
spoofFolder = value.setup.spoofFolder

if spoof:
	eamFolder = spoofFolder
else:
	eamFolder = "[System]Gateway/"

ignitionLevels = ["frontends", "backends", "ios"]
architectureLevels = {"frontends": value.setup.frontends, "backends": value.setup.backends, "ios": value.setup.io}
architecture = {}

for level in architectureLevels:
	if level in ignitionLevels:
		architecture[level] = []
		if level in ["backends"]:
			for backend in architectureLevels[level]:
				architecture[level].append({"server":			backend["master"], 
											"redundantServer":	backend["backup"],
											"type":				level, 
											"redundancy":		system.tag.browse(path = eamFolder+"/EAM/Agents/"+str(backend["master"])+"/", 					filter = {"tagType":"folder"})[0]["name"],
											"status":			[tag for tag in system.tag.browse(path = eamFolder+"/EAM/Agents/"+str(backend["master"])+"/", filter = {"tagType":"AtomicTag", "recursive": True}) if 'Metrics' not in str(tag['fullPath'])], 
											"metrics":			[tag for tag in system.tag.browse(path = eamFolder+"/EAM/Agents/"+str(backend["master"])+"/", filter = {"tagType":"AtomicTag", "recursive": True}) if 'Metrics' in str(tag['fullPath'])],
											"redundantStatus":	[tag for tag in system.tag.browse(path = eamFolder+"/EAM/Agents/"+str(backend["backup"])+"/", filter = {"tagType":"AtomicTag", "recursive": True}) if 'Metrics' not in str(tag['fullPath'])],
											"redundantMetrics":	[tag for tag in system.tag.browse(path = eamFolder+"/EAM/Agents/"+str(backend["backup"])+"/", filter = {"tagType":"AtomicTag", "recursive": True}) if 'Metrics' in str(tag['fullPath'])]})
		else:				
			for count, server in enumerate(architectureLevels[level]):
				architecture[level].append({"server":server, 
											"type":level, 
											"redundancy":system.tag.browse(eamFolder+"/EAM/Agents/"+str(server)+"/", filter={"tagType":"folder"})[0]["name"],
											"status":[tag for tag in system.tag.browse(path = eamFolder+"/EAM/Agents/"+str(server)+"/", filter = {"tagType":"AtomicTag", "recursive": True}) if 'Metrics' not in str(tag['fullPath'])], 
											"metrics":[tag for tag in system.tag.browse(path = eamFolder+"/EAM/Agents/"+str(server)+"/", filter = {"tagType":"AtomicTag", "recursive": True}) if 'Metrics' in str(tag['fullPath'])]})

# Remove whitespace for param naming.
for item in architecture:
	if ' ' in item:
		architecture[item.replace(" ", "")] = architecture[item]
		del architecture[item]

return architecture
